CREATE VIEW expense_order_sources AS SELECT o.id order_id,o.store_id,o.customer_id,o.order_number,v.version,v.status,v.title,v.subtotal_cents FROM retail_orders o JOIN retail_order_versions v ON v.order_id=o.id WHERE v.version=(SELECT max(version) FROM retail_order_versions WHERE order_id=o.id);
CREATE TABLE expense_roots(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),order_id TEXT REFERENCES retail_orders(id),serial INTEGER NOT NULL CHECK(serial>0),record_number TEXT NOT NULL,first_version_id TEXT NOT NULL UNIQUE REFERENCES expense_versions(id) DEFERRABLE INITIALLY DEFERRED,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,record_number),FOREIGN KEY(first_version_id,id) REFERENCES expense_versions(id,root_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE expense_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES expense_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),event_id TEXT NOT NULL UNIQUE REFERENCES expense_events(id) DEFERRABLE INITIALLY DEFERRED,retail_prefix INTEGER NOT NULL CHECK(retail_prefix>=0),order_id TEXT REFERENCES retail_orders(id),order_version INTEGER,order_snapshot_json TEXT CHECK(order_snapshot_json IS NULL OR json_valid(order_snapshot_json)),title TEXT NOT NULL,data_json TEXT NOT NULL CHECK(json_valid(data_json)),reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version),UNIQUE(id,root_id),FOREIGN KEY(event_id,id) REFERENCES expense_events(id,version_id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(order_id,order_version) REFERENCES retail_order_versions(order_id,version));
CREATE TABLE expense_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES expense_roots(id),version_id TEXT NOT NULL REFERENCES expense_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('record','withdraw')),status TEXT NOT NULL CHECK(status IN('recorded','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(id,version_id));
CREATE TABLE expense_payment_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES expense_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),expense_version_id TEXT NOT NULL REFERENCES expense_versions(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('pay','void')),expense_sequence INTEGER NOT NULL CHECK(expense_sequence>=0),retail_prefix INTEGER NOT NULL CHECK(retail_prefix>=0),source_id TEXT UNIQUE REFERENCES expense_payment_events(id),amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents BETWEEN 1 AND 1000000000000),currency TEXT NOT NULL CHECK(currency='CNY'),method TEXT NOT NULL CHECK(method IN('cash','card','transfer','other')),reference_status TEXT NOT NULL CHECK(reference_status IN('unknown','recorded')),reference TEXT,paid_at TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(expense_version_id,root_id) REFERENCES expense_versions(id,root_id));
CREATE VIEW expense_current AS SELECT * FROM expense_events e WHERE revision=(SELECT max(revision) FROM expense_events WHERE root_id=e.root_id);
CREATE TRIGGER expense_root_source BEFORE INSERT ON expense_roots BEGIN SELECT CASE WHEN NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM retail_orders o WHERE o.id=NEW.order_id AND o.store_id=NEW.store_id AND o.created_at<=NEW.created_at) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM expense_roots WHERE store_id=NEW.store_id),1) OR NEW.record_number IS NOT 'EX-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'expense fixed store/original relation/number') END;END;
CREATE TRIGGER expense_version_source BEFORE INSERT ON expense_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expense_roots r WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND r.order_id IS NEW.order_id AND (r.order_id IS NULL AND NEW.order_version IS NULL AND NEW.order_snapshot_json IS NULL OR EXISTS(SELECT 1 FROM expense_order_sources m WHERE m.order_id=r.order_id AND m.store_id=r.store_id AND m.version=NEW.order_version AND NEW.order_snapshot_json=json_object('order_id',m.order_id,'store_id',m.store_id,'customer_id',m.customer_id,'order_number',m.order_number,'version',m.version,'status',m.status,'title',m.title,'subtotal_cents',m.subtotal_cents)))) OR NEW.retail_prefix<>coalesce((SELECT max(v.rowid) FROM retail_order_versions v JOIN retail_orders o ON o.id=v.order_id WHERE o.store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM retail_order_versions v JOIN retail_orders o ON o.id=v.order_id WHERE o.store_id=NEW.store_id AND v.created_at>NEW.created_at) OR NEW.version<>coalesce((SELECT max(version)+1 FROM expense_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM expense_events WHERE store_id=NEW.store_id),0) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM expense_roots r WHERE r.id=NEW.root_id AND r.first_version_id=NEW.id AND r.created_at=NEW.created_at AND r.created_by=NEW.created_by) THEN RAISE(ABORT,'expense current order snapshot/version pairing') END;END;
CREATE TRIGGER expense_event_source BEFORE INSERT ON expense_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expense_versions v WHERE v.id=NEW.version_id AND v.root_id=NEW.root_id AND v.store_id=NEW.store_id) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM expense_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM expense_events WHERE root_id=NEW.root_id),1) OR NEW.action='record' AND (NEW.status<>'recorded' OR NOT EXISTS(SELECT 1 FROM expense_versions v WHERE v.id=NEW.version_id AND v.event_id=NEW.id AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by AND v.reason=NEW.reason AND v.version=coalesce((SELECT max(v2.version)+1 FROM expense_events e JOIN expense_versions v2 ON v2.id=e.version_id WHERE e.root_id=NEW.root_id),1))) THEN RAISE(ABORT,'expense continuous paired event') END;
SELECT CASE WHEN NEW.action='withdraw' AND (NEW.status<>'withdrawn' OR NOT EXISTS(SELECT 1 FROM expense_current e WHERE e.root_id=NEW.root_id AND e.status='recorded' AND e.version_id=NEW.version_id)) THEN RAISE(ABORT,'expense explicit current withdrawal') END;END;
CREATE TRIGGER expense_payment_source BEFORE INSERT ON expense_payment_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM expense_roots r JOIN expense_versions v ON v.root_id=r.id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND v.id=NEW.expense_version_id AND v.store_id=r.store_id AND v.created_at<=NEW.created_at) OR NEW.expense_sequence<>coalesce((SELECT max(sequence) FROM expense_events WHERE store_id=NEW.store_id),0) OR NEW.retail_prefix<>coalesce((SELECT max(v.rowid) FROM retail_order_versions v JOIN retail_orders o ON o.id=v.order_id WHERE o.store_id=NEW.store_id),0) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM expense_payment_events WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM expense_payment_events WHERE root_id=NEW.root_id),1) THEN RAISE(ABORT,'expense payment fixed material and continuous facts') END;
SELECT CASE WHEN NEW.action='pay' AND (NEW.source_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM expense_current e JOIN expense_versions v ON v.id=e.version_id WHERE e.root_id=NEW.root_id AND e.status='recorded' AND e.version_id=NEW.expense_version_id AND (v.order_id IS NULL OR EXISTS(SELECT 1 FROM expense_order_sources m WHERE m.order_id=v.order_id AND m.store_id=v.store_id AND v.order_snapshot_json=json_object('order_id',m.order_id,'store_id',m.store_id,'customer_id',m.customer_id,'order_number',m.order_number,'version',m.version,'status',m.status,'title',m.title,'subtotal_cents',m.subtotal_cents))))) THEN RAISE(ABORT,'expense payment explicitly adopts current material/original order') END;
SELECT CASE WHEN NEW.action='void' AND NOT EXISTS(SELECT 1 FROM expense_payment_events p WHERE p.id=NEW.source_id AND p.root_id=NEW.root_id AND p.store_id=NEW.store_id AND p.action='pay' AND p.expense_version_id=NEW.expense_version_id AND p.amount_cents=NEW.amount_cents AND p.currency=NEW.currency AND p.method=NEW.method AND p.reference_status=NEW.reference_status AND p.reference IS NEW.reference AND p.paid_at=NEW.paid_at AND p.created_at<=NEW.created_at) THEN RAISE(ABORT,'expense void preserves original false payment; no second cash movement') END;
SELECT CASE WHEN length(NEW.paid_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.paid_at) IS NOT NEW.paid_at OR NEW.paid_at>NEW.created_at OR (NEW.reference_status='unknown' AND NEW.reference IS NOT NULL) OR (NEW.reference_status='recorded' AND (NEW.reference IS NULL OR length(trim(NEW.reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.reference)>1000 OR instr(NEW.reference,char(0))>0)) THEN RAISE(ABORT,'expense explicit actual payment date/reference') END;END;
CREATE TRIGGER expense_typed_data BEFORE INSERT ON expense_versions WHEN NOT (NEW.data_json=json_object('expense_label',json_extract(NEW.data_json,'$.expense_label'),'reference_status',json_extract(NEW.data_json,'$.reference_status'),'reference',json_extract(NEW.data_json,'$.reference'),'evidence_date_status',json_extract(NEW.data_json,'$.evidence_date_status'),'evidence_date',json_extract(NEW.data_json,'$.evidence_date'),'amount_status',json_extract(NEW.data_json,'$.amount_status'),'amount_cents',json_extract(NEW.data_json,'$.amount_cents'),'counterparty_status',json_extract(NEW.data_json,'$.counterparty_status'),'counterparty_note',json_extract(NEW.data_json,'$.counterparty_note'),'purpose_note',json_extract(NEW.data_json,'$.purpose_note'),'source_note',json_extract(NEW.data_json,'$.source_note')) AND (json_type(NEW.data_json,'$.expense_label') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.expense_label'))) BETWEEN 1 AND 300 AND length(json_extract(NEW.data_json,'$.expense_label'))<=300 AND instr(json_extract(NEW.data_json,'$.expense_label'),char(0))=0) AND (json_type(NEW.data_json,'$.purpose_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.purpose_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.purpose_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.purpose_note'),char(0))=0) AND (json_type(NEW.data_json,'$.source_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.source_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.source_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.source_note'),char(0))=0) AND json_type(NEW.data_json,'$.reference_status') IS 'text' AND (json_extract(NEW.data_json,'$.reference_status')='unknown' AND json_type(NEW.data_json,'$.reference')='null' OR json_extract(NEW.data_json,'$.reference_status')='recorded' AND ((json_type(NEW.data_json,'$.reference') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.reference'))) BETWEEN 1 AND 1000 AND length(json_extract(NEW.data_json,'$.reference'))<=1000 AND instr(json_extract(NEW.data_json,'$.reference'),char(0))=0))) AND json_type(NEW.data_json,'$.evidence_date_status') IS 'text' AND (json_extract(NEW.data_json,'$.evidence_date_status')='unknown' AND json_type(NEW.data_json,'$.evidence_date')='null' OR json_extract(NEW.data_json,'$.evidence_date_status')='recorded' AND (json_type(NEW.data_json,'$.evidence_date') IS 'text' AND length(json_extract(NEW.data_json,'$.evidence_date'))=10 AND date(json_extract(NEW.data_json,'$.evidence_date'),'+0 days') IS json_extract(NEW.data_json,'$.evidence_date') AND json_extract(NEW.data_json,'$.evidence_date')<=substr(NEW.created_at,1,10))) AND json_type(NEW.data_json,'$.amount_status') IS 'text' AND (json_extract(NEW.data_json,'$.amount_status')='unknown' AND json_type(NEW.data_json,'$.amount_cents')='null' OR json_extract(NEW.data_json,'$.amount_status')='recorded' AND (json_type(NEW.data_json,'$.amount_cents') IS 'integer' AND json_extract(NEW.data_json,'$.amount_cents') BETWEEN 0 AND 1000000000000)) AND json_type(NEW.data_json,'$.counterparty_status') IS 'text' AND (json_extract(NEW.data_json,'$.counterparty_status')='unknown' AND json_type(NEW.data_json,'$.counterparty_note')='null' OR json_extract(NEW.data_json,'$.counterparty_status')='recorded' AND ((json_type(NEW.data_json,'$.counterparty_note') IS 'text' AND length(trim(json_extract(NEW.data_json,'$.counterparty_note'))) BETWEEN 1 AND 2000 AND length(json_extract(NEW.data_json,'$.counterparty_note'))<=2000 AND instr(json_extract(NEW.data_json,'$.counterparty_note'),char(0))=0)))) BEGIN SELECT RAISE(ABORT,'expense explicit canonical material/unknowns');END;
CREATE TRIGGER expense_roots_actor BEFORE INSERT ON expense_roots WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM expense_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM expense_payment_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'expense current actor/time');END;
CREATE TRIGGER expense_roots_no_update BEFORE UPDATE ON expense_roots BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_roots_no_delete BEFORE DELETE ON expense_roots BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_versions_actor BEFORE INSERT ON expense_versions WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM expense_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM expense_payment_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'expense current actor/time');END;
CREATE TRIGGER expense_versions_no_update BEFORE UPDATE ON expense_versions BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_versions_no_delete BEFORE DELETE ON expense_versions BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_versions_text BEFORE INSERT ON expense_versions WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.title)) NOT BETWEEN 1 AND 160 OR length(NEW.title)>160 OR instr(NEW.title,char(0))>0 BEGIN SELECT RAISE(ABORT,'expense explicit text');END;
CREATE TRIGGER expense_events_actor BEFORE INSERT ON expense_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM expense_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM expense_payment_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'expense current actor/time');END;
CREATE TRIGGER expense_events_no_update BEFORE UPDATE ON expense_events BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_events_no_delete BEFORE DELETE ON expense_events BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_events_text BEFORE INSERT ON expense_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 OR instr(NEW.next_step,char(0))>0 BEGIN SELECT RAISE(ABORT,'expense explicit text');END;
CREATE TRIGGER expense_payment_events_actor BEFORE INSERT ON expense_payment_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role='manager' AND u.active=1 AND coalesce(s.must_change_password,0)=0) OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM expense_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM expense_payment_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'expense current actor/time');END;
CREATE TRIGGER expense_payment_events_no_update BEFORE UPDATE ON expense_payment_events BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_payment_events_no_delete BEFORE DELETE ON expense_payment_events BEGIN SELECT RAISE(ABORT,'expense immutable');END;
CREATE TRIGGER expense_payment_events_text BEFORE INSERT ON expense_payment_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR instr(NEW.reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'expense explicit text');END;
